        int a, b;
        ll w;
        cin >> a >> b >> w;
        g.add(a, b, w);
    }
    for (int a = 1; a <= n; a++) {
        for (int b = 1; b <= n; b++) {
            if (b > 1) cout << ' ';
            if (g.has[a][b]) cout << g.weight[a][b];
            else cout << '.';
        }
        cout << '\n';
    }
}

